A="$A" B="$B" PROD="$PROD" SUM="$SUM" NEG="$NEG" node -e '
const A=BigInt(process.env.A.replace(/_/g,"")),B=BigInt(process.env.B.replace(/_/g,""));
const okP=(A*B).toString()===process.env.PROD;
const okS=(A+B).toString()===process.env.SUM;
const okN=(-A).toString()===process.env.NEG;
console.log("product_matches_bigint="+okP+" sum_matches="+okS+" neg_matches="+okN);
if(!okP){console.log("expected="+(A*B).toString());console.log("got     ="+process.env.PROD);}
if(!okN){console.log("neg_expected="+(-A).toString()+" got="+process.env.NEG);}
'
# check encoded line 1 equals reconstruction
A="$A" B="$B" L1="$L1" node -e '
const A=BigInt(process.env.A.replace(/_/g,"")),B=BigInt(process.env.B.replace(/_/g,""));
