cat >/tmp/chk.js <<'JSEOF'
const A=BigInt(process.env.A.replace(/_/g,''));
const B=BigInt(process.env.B.replace(/_/g,''));
const q=String.fromCharCode(39);
const enc=x=>'i'+x.toString()+'e';
const l1='b'+q+'l'+enc(A)+enc(B)+enc(A+B)+enc(A*B)+'e'+q;
const l2='['+[A,B,A+B,A*B].map(x=>x.toString()).join(', ')+']';
const l3='b'+q+enc(-A)+q;
const l4='b'+q+'i0e'+q;
const exp=[l1,l2,l3,l4].join('\n')+'\n';
const got=require('fs').readFileSync(process.env.OUTF,'utf8');
console.log('FULL_STDOUT_MATCHES_MODEL='+(exp===got));
if(exp!==got){
  const el=exp.split('\n'),gl=got.split('\n');
  for(let i=0;i<Math.max(el.length,gl.length);i++){
    if(el[i]!==gl[i]){console.log('DIFF line '+(i+1));console.log('EXP['+i+']='+el[i]);console.log('GOT['+i+']='+gl[i]);}
  }
}
